class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int n = arr.size();
        long long noDelete = arr[0];
        long long oneDelete = LLONG_MIN / 2; // cannot delete from a single element
        long long ans = arr[0];
        for (int i = 1; i < n; i++) {
            long long newNoDelete = max((long long)arr[i], noDelete + arr[i]);
            long long newOneDelete = max(noDelete, oneDelete + arr[i]);
            noDelete = newNoDelete;
            oneDelete = newOneDelete;
            ans = max(ans, max(noDelete, oneDelete));
        }
        return (int)ans;
    }
};
